<?php
require dirname(__DIR__).'/includes/bootstrap.php';require_permission('dashboard.view');$pdo=db();ensure_runtime_schema();$campaign=$pdo->query("SELECT * FROM campaigns WHERE status='active' ORDER BY start_date DESC,id DESC LIMIT 1")->fetch();if(!$campaign)$campaign=['id'=>0,'name'=>'No active campaign','start_date'=>date('Y-m-d'),'deadline'=>date('Y-m-d'),'target_count'=>1,'timezone'=>config('app.timezone')];$growth=growth_count_summary();$q=$pdo->prepare('SELECT COALESCE(SUM(drivers_registered),0) FROM daily_growth_counts WHERE activity_date BETWEEN ? AND ?');$q->execute([$campaign['start_date'],$campaign['deadline']]);$counted=(int)$q->fetchColumn();$progress=campaign_progress($campaign,$counted,$growth['today_drivers']);$totalDrivers=$growth['total_drivers'];$pending=(int)$pdo->query("SELECT COUNT(*) FROM tasks WHERE status NOT IN ('completed','cancelled')")->fetchColumn();$overdue=(int)$pdo->query("SELECT COUNT(*) FROM tasks WHERE status NOT IN ('completed','cancelled') AND due_at IS NOT NULL AND due_at<UTC_TIMESTAMP()")->fetchColumn();$completed=(int)$pdo->query("SELECT COUNT(*) FROM tasks WHERE status='completed'")->fetchColumn();$activeEmployees=(int)$pdo->query("SELECT COUNT(*) FROM employees WHERE employment_status='active'")->fetchColumn();json_response(['ok'=>true,'data'=>compact('progress','growth','totalDrivers','pending','overdue','completed','activeEmployees')]);
